 README.org                     |  1 +
 modules/home-manager/herdr.nix | 16 ++++++++++++++++
 2 files changed, 17 insertions(+)
diff --git c/README.org i/README.org
index acce800..d87fc94 100644
--- c/README.org
+++ i/README.org
@@ -197,6 +197,7 @@ Update it whenever the bindings in ~herdr.nix~ change.
 | ~prefix S-Tab~                 | jump to agent needing attention | ~BTab~ tmux-jump-bell | latest blocked, else latest done; ~prefix o~ needs an in-app toast |
 | ~prefix g~ ~B~                 | agent picker                  | ~B~ tmux-jump-bell    | press ~b~ to filter blocked agents                           |
 | ~prefix ]~                     | paste clipboard               | ~paste-buffer~        | herdr has no paste buffer; command is ~webframp.herdr.pasteCommand~ |
+| ~prefix Y~                     | copy pane directory           | none                  | command is ~webframp.herdr.copyCommand~                      |
 | ~prefix u~                     | open URL from pane            | fzf-tmux-url          | opener is ~webframp.herdr.urlOpener~                         |
 | ~prefix f~                     | open project workspace        | none                  | zoxide recency, then repos under ~projectRoots~              |
 | ~prefix A~                     | new agent in its own worktree | none                  | kinds from ~agentKinds~; checkout under ~worktreesDirectory~ |
diff --git c/modules/home-manager/herdr.nix i/modules/home-manager/herdr.nix
index 787a036..3dc67b3 100644
--- c/modules/home-manager/herdr.nix
+++ i/modules/home-manager/herdr.nix
@@ -37,6 +37,15 @@ in {
       description = "Command the prefix+u URL popup passes selected URLs to (e.g. wslview for WSL)";
     };

+    copyCommand = lib.mkOption {
+      type = lib.types.str;
+      default =
+        if pkgs.stdenv.hostPlatform.isDarwin
+        then "pbcopy"
+        else "xclip -i -selection clipboard";
+      description = "Command that writes stdin to the system clipboard, for the prefix+Y yank binding";
+    };
+
     pasteCommand = lib.mkOption {
       type = lib.types.str;
       default =
@@ -173,6 +182,13 @@ in {
             description = "paste clipboard";
             command = "${cfg.pasteCommand} | ${launch "paste"}";
           }
+          # Yank the active pane's directory. xclip lingers to serve the selection, so detach its output.
+          {
+            key = "prefix+shift+y";
+            type = "shell";
+            description = "copy pane directory";
+            command = ''dir=''${HERDR_ACTIVE_PANE_CWD:-$PWD}; printf '%s' "$dir" | ${cfg.copyCommand} >/dev/null 2>&1 && "$HERDR_BIN_PATH" notification show "Copied $dir" >/dev/null'';
+          }
           # Project workspace from a recency-ranked fzf list (zoxide, then projectRoots).
           {
             key = "prefix+f";

